$(document).ready( () => {
  $("#email_form").submit( evt => {
    const email = $("#email").val().trim();
    if (email === "" || email.indexOf("@") === -1) {
      $("#email").next().text("Enter a valid email.");
      evt.preventDefault();
    } else {
      $("#email").next().text("");
    }
  });
});

